"use client";

import { useEffect, useRef, useState } from "react";
import { supabase } from "@/lib/supabase";

/*
 * ============================================================
 * STUDY TOOLS — Quiz, Key Topics, Flowchart
 * ============================================================
 * Everything is generated by /api/ai/study-tools from the
 * subject's own prepared documents.
 * ============================================================
 */

type Tool = "quiz" | "topics" | "flowchart";

type QuizQuestion = {
  question: string;
  options: string[];
  answerIndex: number;
  explanation: string;
  source: string;
};

type Topic = {
  title: string;
  summary: string;
  importance: "high" | "medium" | "low";
  keyPoints: string[];
  sources: string[];
};

type TopicsResult = {
  overview: string;
  topics: Topic[];
};

type FlowchartResult = {
  title: string;
  stages: {
    title: string;
    description: string;
    concepts: string[];
  }[];
  connections: {
    from: string;
    to: string;
    relation: string;
  }[];
};

type StudyToolsProps = {
  subjectId: string;
  subjectName: string;
  documentCount: number;
};

const QUIZ_COUNTS = [10, 15, 20, 25];
const OPTION_LETTERS = ["A", "B", "C", "D"];

const TOOL_CARDS: {
  tool: Tool;
  icon: string;
  title: string;
  description: string;
  action: string;
}[] = [
  {
    tool: "quiz",
    icon: "🏆",
    title: "Generate Quiz",
    description: "Practice questions written from your own documents.",
    action: "Start quiz",
  },
  {
    tool: "topics",
    icon: "☷",
    title: "Key Topics",
    description: "The concepts that matter most, ranked by importance.",
    action: "Explore topics",
  },
  {
    tool: "flowchart",
    icon: "↗",
    title: "Subject Flowchart",
    description: "See how the ideas build on and connect to each other.",
    action: "Visualize",
  },
];

const LOADING_LINES: Record<Tool, string> = {
  quiz: "Writing questions from your material",
  topics: "Finding the most important topics",
  flowchart: "Mapping how the concepts connect",
};

// ============================================================
// SHARED REQUEST HELPER
// ============================================================

async function requestStudyTool(body: {
  subjectId: string;
  tool: Tool;
  count?: number;
  focus?: string;
}) {
  const {
    data: { session },
  } = await supabase.auth.getSession();

  if (!session?.access_token) {
    throw new Error("Please sign in again to use study tools.");
  }

  const response = await fetch("/api/ai/study-tools", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${session.access_token}`,
    },
    body: JSON.stringify(body),
  });

  const data = await response.json().catch(() => null);

  if (!response.ok || !data?.result) {
    throw new Error(
      data?.error || `Something went wrong (${response.status}). Please try again.`
    );
  }

  return data as {
    result: unknown;
    documentsUsed: string[];
  };
}

// ============================================================
// MAIN COMPONENT
// ============================================================

export default function StudyTools({
  subjectId,
  subjectName,
  documentCount,
}: StudyToolsProps) {
  const [activeTool, setActiveTool] = useState<Tool>("quiz");

  const [loadingTool, setLoadingTool] = useState<Tool | null>(null);
  const [elapsed, setElapsed] = useState(0);
  const [errors, setErrors] = useState<Partial<Record<Tool, string>>>({});

  // Quiz
  const [quizCount, setQuizCount] = useState(10);
  const [quizFocus, setQuizFocus] = useState("");
  const [quiz, setQuiz] = useState<QuizQuestion[] | null>(null);

  // Topics + flowchart
  const [topics, setTopics] = useState<TopicsResult | null>(null);
  const [flowchart, setFlowchart] = useState<FlowchartResult | null>(null);
  const [documentsUsed, setDocumentsUsed] = useState<
    Partial<Record<Tool, string[]>>
  >({});

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, []);

  const hasDocuments = documentCount > 0;

  async function generate(tool: Tool) {
    if (loadingTool) {
      return;
    }

    setLoadingTool(tool);
    setErrors((current) => ({ ...current, [tool]: "" }));
    setElapsed(0);

    timerRef.current = setInterval(() => {
      setElapsed((seconds) => seconds + 1);
    }, 1000);

    try {
      const data = await requestStudyTool({
        subjectId,
        tool,
        count: tool === "quiz" ? quizCount : undefined,
        focus: tool === "quiz" ? quizFocus.trim() : undefined,
      });

      setDocumentsUsed((current) => ({
        ...current,
        [tool]: data.documentsUsed,
      }));

      if (tool === "quiz") {
        setQuiz((data.result as { questions: QuizQuestion[] }).questions);
      } else if (tool === "topics") {
        setTopics(data.result as TopicsResult);
      } else {
        setFlowchart(data.result as FlowchartResult);
      }
    } catch (error) {
      setErrors((current) => ({
        ...current,
        [tool]:
          error instanceof Error
            ? error.message
            : "Something went wrong. Please try again.",
      }));
    } finally {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }

      setLoadingTool(null);
    }
  }

  return (
    <section className="mt-10">
      <div className="mb-6">
        <p className="mb-2 text-sm font-medium tracking-wide text-accent">
          STUDY TOOLS
        </p>

        <h2 className="font-serif text-4xl tracking-tight">
          Supercharge your learning
        </h2>

        <p className="mt-2 max-w-2xl text-sm leading-6 text-muted">
          Turn your {subjectName} material into practice, priorities, and a
          map of how everything connects. Everything is generated only from
          your uploaded documents.
        </p>
      </div>

      {/* Tool cards */}
      <div className="grid gap-5 md:grid-cols-3">
        {TOOL_CARDS.map((card) => (
          <button
            key={card.tool}
            onClick={() => setActiveTool(card.tool)}
            className={`group rounded-3xl border p-7 text-left transition-all ${
              activeTool === card.tool
                ? "border-accent bg-card shadow-sm"
                : "border-border bg-card hover:-translate-y-0.5 hover:shadow-sm"
            }`}
          >
            <div className="mb-6 flex h-14 w-14 items-center justify-center rounded-2xl bg-background text-2xl">
              {card.icon}
            </div>

            <p className="font-serif text-2xl">{card.title}</p>

            <p className="mt-2 text-sm leading-6 text-muted">
              {card.description}
            </p>

            <div className="mt-6 flex items-center text-sm font-medium text-accent">
              {card.action}
              <span className="ml-2 transition-transform group-hover:translate-x-1">
                →
              </span>
            </div>
          </button>
        ))}
      </div>

      {/* Active panel */}
      <div className="mt-6 rounded-3xl border border-border bg-card p-7 shadow-sm md:p-8">
        {!hasDocuments ? (
          <EmptyState />
        ) : loadingTool === activeTool ? (
          <LoadingState tool={activeTool} elapsed={elapsed} />
        ) : (
          <>
            {errors[activeTool] && (
              <div className="mb-6 rounded-2xl border border-red-200 bg-red-50 px-5 py-4 text-sm text-red-700">
                {errors[activeTool]}
              </div>
            )}

            {activeTool === "quiz" &&
              (quiz ? (
                <QuizPlayer
                  key={quiz.map((q) => q.question).join("|")}
                  questions={quiz}
                  subjectName={subjectName}
                  onNewQuiz={() => setQuiz(null)}
                />
              ) : (
                <QuizSetup
                  subjectName={subjectName}
                  count={quizCount}
                  focus={quizFocus}
                  disabled={loadingTool !== null}
                  onCountChange={setQuizCount}
                  onFocusChange={setQuizFocus}
                  onStart={() => generate("quiz")}
                />
              ))}

            {activeTool === "topics" &&
              (topics ? (
                <TopicsView
                  data={topics}
                  documentsUsed={documentsUsed.topics ?? []}
                  disabled={loadingTool !== null}
                  onRegenerate={() => generate("topics")}
                />
              ) : (
                <ToolIntro
                  badge="KNOW WHAT MATTERS"
                  title="Key topics"
                  text={`Find the most important concepts across all your ${subjectName} documents, ranked by importance, with key points and where each one appears.`}
                  button="Find key topics"
                  disabled={loadingTool !== null}
                  onStart={() => generate("topics")}
                />
              ))}

            {activeTool === "flowchart" &&
              (flowchart ? (
                <FlowchartView
                  data={flowchart}
                  documentsUsed={documentsUsed.flowchart ?? []}
                  disabled={loadingTool !== null}
                  onRegenerate={() => generate("flowchart")}
                />
              ) : (
                <ToolIntro
                  badge="VISUAL LEARNING"
                  title="Subject flowchart"
                  text={`Build a step-by-step map of how the ideas in ${subjectName} build on each other — click any concept to see what it connects to.`}
                  button="Build flowchart"
                  disabled={loadingTool !== null}
                  onStart={() => generate("flowchart")}
                />
              ))}
          </>
        )}
      </div>
    </section>
  );
}

// ============================================================
// SMALL SHARED PIECES
// ============================================================

function EmptyState() {
  return (
    <div className="rounded-2xl border border-dashed border-border bg-background p-10 text-center">
      <p className="font-serif text-2xl">Add documents first</p>
      <p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted">
        Upload your study material above. Quizzes, key topics, and flowcharts
        are generated only from your own documents.
      </p>
    </div>
  );
}

function LoadingState({ tool, elapsed }: { tool: Tool; elapsed: number }) {
  return (
    <div className="flex flex-col items-center justify-center py-14 text-center">
      <div className="h-12 w-12 animate-spin rounded-full border-4 border-border border-t-accent" />

      <p className="mt-6 font-serif text-2xl">{LOADING_LINES[tool]}…</p>

      <p className="mt-2 text-sm text-muted">
        {elapsed}s — this usually takes 15–40 seconds.
      </p>
    </div>
  );
}

function ToolIntro({
  badge,
  title,
  text,
  button,
  disabled,
  onStart,
}: {
  badge: string;
  title: string;
  text: string;
  button: string;
  disabled: boolean;
  onStart: () => void;
}) {
  return (
    <div className="py-4">
      <div className="mb-4 inline-flex rounded-full bg-background px-4 py-2 text-xs font-medium text-accent">
        {badge}
      </div>

      <h3 className="font-serif text-3xl md:text-4xl">{title}</h3>

      <p className="mt-3 max-w-2xl text-sm leading-7 text-muted">{text}</p>

      <button
        onClick={onStart}
        disabled={disabled}
        className="mt-7 rounded-full bg-accent px-7 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
      >
        {button} →
      </button>
    </div>
  );
}

function SourcesLine({ sources }: { sources: string[] }) {
  if (sources.length === 0) {
    return null;
  }

  return (
    <p className="mt-6 text-xs leading-5 text-muted">
      Based on: {sources.join(" · ")}
    </p>
  );
}

// ============================================================
// QUIZ
// ============================================================

function QuizSetup({
  subjectName,
  count,
  focus,
  disabled,
  onCountChange,
  onFocusChange,
  onStart,
}: {
  subjectName: string;
  count: number;
  focus: string;
  disabled: boolean;
  onCountChange: (count: number) => void;
  onFocusChange: (focus: string) => void;
  onStart: () => void;
}) {
  return (
    <div className="grid gap-8 lg:grid-cols-[1.2fr_0.8fr] lg:items-center">
      <div>
        <div className="mb-5 inline-flex rounded-full bg-background px-4 py-2 text-xs font-medium text-accent">
          QUICK CHALLENGE
        </div>

        <h3 className="font-serif text-3xl md:text-4xl">
          Ready to test yourself?
        </h3>

        <p className="mt-3 max-w-xl text-sm leading-7 text-muted">
          Choose how many questions you want and turn your {subjectName}{" "}
          material into a focused practice session.
        </p>

        <div className="mt-7">
          <p className="mb-3 text-sm font-medium">Number of questions</p>

          <div className="grid grid-cols-4 gap-2">
            {QUIZ_COUNTS.map((option) => (
              <button
                key={option}
                onClick={() => onCountChange(option)}
                className={`rounded-xl border px-3 py-3 text-sm font-medium transition ${
                  count === option
                    ? "border-accent bg-accent text-white"
                    : "border-border bg-background hover:bg-card"
                }`}
              >
                {option}
              </button>
            ))}
          </div>
        </div>

        <div className="mt-6">
          <label htmlFor="quizFocus" className="mb-2 block text-sm font-medium">
            Focus on a topic <span className="font-normal text-muted">(optional)</span>
          </label>

          <input
            id="quizFocus"
            type="text"
            value={focus}
            maxLength={120}
            onChange={(event) => onFocusChange(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === "Enter" && !disabled) {
                onStart();
              }
            }}
            placeholder="e.g. Session 3, pricing strategy"
            className="w-full rounded-xl border border-border bg-background px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-accent"
          />
        </div>

        <button
          onClick={onStart}
          disabled={disabled}
          className="mt-7 rounded-full bg-accent px-7 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
        >
          Start {count}-question quiz →
        </button>
      </div>

      <div className="rounded-3xl border border-border bg-background p-7">
        <p className="text-sm font-medium text-accent">YOUR QUIZ</p>

        <div className="mt-6 flex items-center justify-center">
          <div className="flex h-36 w-36 flex-col items-center justify-center rounded-full border-8 border-border">
            <span className="font-serif text-4xl">{count}</span>
            <span className="mt-1 text-xs text-muted">questions</span>
          </div>
        </div>

        <div className="mt-7 space-y-3 text-sm">
          <div className="flex justify-between rounded-xl bg-card px-4 py-3">
            <span className="text-muted">Subject</span>
            <span className="max-w-[55%] truncate font-medium">{subjectName}</span>
          </div>

          <div className="flex justify-between rounded-xl bg-card px-4 py-3">
            <span className="text-muted">Focus</span>
            <span className="max-w-[55%] truncate font-medium">
              {focus.trim() || "Whole subject"}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}

function QuizPlayer({
  questions,
  subjectName,
  onNewQuiz,
}: {
  questions: QuizQuestion[];
  subjectName: string;
  onNewQuiz: () => void;
}) {
  const [current, setCurrent] = useState(0);
  const [answers, setAnswers] = useState<(number | null)[]>(() =>
    questions.map(() => null)
  );
  const [finished, setFinished] = useState(false);

  const score = answers.filter(
    (answer, index) => answer === questions[index].answerIndex
  ).length;

  function choose(optionIndex: number) {
    if (answers[current] !== null) {
      return;
    }

    setAnswers((existing) =>
      existing.map((answer, index) => (index === current ? optionIndex : answer))
    );
  }

  function retake() {
    setAnswers(questions.map(() => null));
    setCurrent(0);
    setFinished(false);
  }

  if (finished) {
    const percent = Math.round((score / questions.length) * 100);
    const message =
      percent >= 80
        ? "Excellent — you know this material well."
        : percent >= 50
          ? "Good progress. Review the ones you missed below."
          : "Keep going — the explanations below will help.";

    return (
      <div>
        <div className="rounded-3xl border border-border bg-background p-8 text-center">
          <p className="text-sm font-medium text-accent">QUIZ COMPLETE</p>

          <p className="mt-4 font-serif text-6xl">
            {score}
            <span className="text-3xl text-muted">/{questions.length}</span>
          </p>

          <p className="mt-2 text-sm text-muted">
            {percent}% · {message}
          </p>

          <div className="mt-6 flex flex-wrap justify-center gap-3">
            <button
              onClick={retake}
              className="rounded-full border border-border px-6 py-3 text-sm font-medium transition hover:bg-card"
            >
              Retake this quiz
            </button>

            <button
              onClick={onNewQuiz}
              className="rounded-full bg-accent px-6 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90"
            >
              New quiz
            </button>
          </div>
        </div>

        <h4 className="mt-8 font-serif text-2xl">Review your answers</h4>

        <div className="mt-4 space-y-3">
          {questions.map((question, index) => {
            const correct = answers[index] === question.answerIndex;

            return (
              <div
                key={index}
                className="rounded-2xl border border-border bg-background p-5"
              >
                <p className="text-sm font-medium">
                  <span className={correct ? "text-green-700" : "text-red-600"}>
                    {correct ? "✓" : "✗"}
                  </span>{" "}
                  {index + 1}. {question.question}
                </p>

                {!correct && answers[index] !== null && (
                  <p className="mt-2 text-sm text-red-600">
                    Your answer: {question.options[answers[index] as number]}
                  </p>
                )}

                <p className="mt-2 text-sm text-green-700">
                  Correct answer: {question.options[question.answerIndex]}
                </p>

                {question.explanation && (
                  <p className="mt-2 text-sm leading-6 text-muted">
                    {question.explanation}
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  const question = questions[current];
  const selected = answers[current];
  const answered = selected !== null;
  const isLast = current === questions.length - 1;

  return (
    <div>
      {/* Progress */}
      <div className="flex items-center justify-between text-sm text-muted">
        <span>
          {subjectName} · Question {current + 1} of {questions.length}
        </span>
        <span>Score: {score}</span>
      </div>

      <div className="mt-3 h-2 overflow-hidden rounded-full bg-background">
        <div
          className="h-full rounded-full bg-accent transition-all"
          style={{
            width: `${((current + (answered ? 1 : 0)) / questions.length) * 100}%`,
          }}
        />
      </div>

      {/* Question */}
      <h3 className="mt-8 font-serif text-2xl leading-snug md:text-3xl">
        {question.question}
      </h3>

      <div className="mt-6 space-y-3">
        {question.options.map((option, index) => {
          const isCorrect = index === question.answerIndex;
          const isChosen = index === selected;

          let style = "border-border bg-background hover:bg-card";

          if (answered && isCorrect) {
            style = "border-green-600 bg-green-50 text-green-900";
          } else if (answered && isChosen) {
            style = "border-red-500 bg-red-50 text-red-900";
          } else if (answered) {
            style = "border-border bg-background opacity-60";
          }

          return (
            <button
              key={index}
              onClick={() => choose(index)}
              disabled={answered}
              className={`flex w-full items-start gap-4 rounded-2xl border px-5 py-4 text-left text-sm transition ${style}`}
            >
              <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full border border-current text-xs font-semibold">
                {OPTION_LETTERS[index]}
              </span>
              <span className="pt-1 leading-6">{option}</span>
            </button>
          );
        })}
      </div>

      {/* Feedback */}
      {answered && (
        <div className="mt-6 rounded-2xl bg-background p-5">
          <p
            className={`text-sm font-semibold ${
              selected === question.answerIndex ? "text-green-700" : "text-red-600"
            }`}
          >
            {selected === question.answerIndex ? "Correct!" : "Not quite."}
          </p>

          {question.explanation && (
            <p className="mt-2 text-sm leading-6 text-muted">
              {question.explanation}
            </p>
          )}

          {question.source && (
            <p className="mt-2 text-xs text-muted">Source: {question.source}</p>
          )}
        </div>
      )}

      {/* Navigation */}
      <div className="mt-8 flex items-center justify-between gap-3">
        <button
          onClick={onNewQuiz}
          className="text-sm text-muted underline-offset-4 hover:underline"
        >
          Quit quiz
        </button>

        <button
          onClick={() => (isLast ? setFinished(true) : setCurrent(current + 1))}
          disabled={!answered}
          className="rounded-full bg-accent px-7 py-3 text-sm font-medium text-white transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-40"
        >
          {isLast ? "See results →" : "Next question →"}
        </button>
      </div>
    </div>
  );
}

// ============================================================
// KEY TOPICS
// ============================================================

const IMPORTANCE_STYLES: Record<Topic["importance"], string> = {
  high: "bg-accent text-white",
  medium: "bg-background text-foreground border border-border",
  low: "bg-background text-muted border border-border",
};

function TopicsView({
  data,
  documentsUsed,
  disabled,
  onRegenerate,
}: {
  data: TopicsResult;
  documentsUsed: string[];
  disabled: boolean;
  onRegenerate: () => void;
}) {
  const [filter, setFilter] = useState<"all" | Topic["importance"]>("all");
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  const visible = data.topics
    .map((topic, index) => ({ topic, index }))
    .filter(({ topic }) => filter === "all" || topic.importance === filter);

  return (
    <div>
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="mb-3 inline-flex rounded-full bg-background px-4 py-2 text-xs font-medium text-accent">
            KNOW WHAT MATTERS
          </div>
          <h3 className="font-serif text-3xl">Key topics</h3>
        </div>

        <button
          onClick={onRegenerate}
          disabled={disabled}
          className="self-start rounded-full border border-border px-5 py-2.5 text-sm transition hover:bg-background disabled:opacity-40"
        >
          ↻ Regenerate
        </button>
      </div>

      {data.overview && (
        <div className="mt-6 rounded-2xl bg-background p-6">
          <p className="text-xs font-medium tracking-wide text-accent">
            SUBJECT OVERVIEW
          </p>
          <p className="mt-2 text-sm leading-7">{data.overview}</p>
        </div>
      )}

      <div className="mt-6 flex flex-wrap gap-2">
        {(["all", "high", "medium", "low"] as const).map((option) => (
          <button
            key={option}
            onClick={() => setFilter(option)}
            className={`rounded-full px-4 py-2 text-xs font-medium capitalize transition ${
              filter === option
                ? "bg-accent text-white"
                : "border border-border bg-background hover:bg-card"
            }`}
          >
            {option === "all"
              ? `All (${data.topics.length})`
              : `${option} (${data.topics.filter((t) => t.importance === option).length})`}
          </button>
        ))}
      </div>

      <div className="mt-6 grid gap-4 md:grid-cols-2">
        {visible.map(({ topic, index }) => {
          const open = openIndex === index;

          return (
            <button
              key={index}
              onClick={() => setOpenIndex(open ? null : index)}
              className={`flex flex-col self-start rounded-2xl border bg-background p-6 text-left transition ${
                open ? "border-accent" : "border-border hover:shadow-sm"
              }`}
            >
              <div className="flex items-start justify-between gap-3">
                <p className="font-serif text-xl leading-snug">
                  <span className="mr-2 text-muted">{index + 1}.</span>
                  {topic.title}
                </p>

                <span
                  className={`shrink-0 rounded-full px-3 py-1 text-[11px] font-medium uppercase tracking-wide ${IMPORTANCE_STYLES[topic.importance]}`}
                >
                  {topic.importance}
                </span>
              </div>

              <p className="mt-3 text-sm leading-6 text-muted">{topic.summary}</p>

              {open && topic.keyPoints.length > 0 && (
                <ul className="mt-4 space-y-2 border-t border-border pt-4">
                  {topic.keyPoints.map((point, pointIndex) => (
                    <li key={pointIndex} className="flex gap-2 text-sm leading-6">
                      <span className="text-accent">•</span>
                      <span>{point}</span>
                    </li>
                  ))}
                </ul>
              )}

              {open && topic.sources.length > 0 && (
                <p className="mt-4 text-xs text-muted">
                  Found in: {topic.sources.join(" · ")}
                </p>
              )}

              {!open && (
                <p className="mt-4 text-xs font-medium text-accent">
                  Show key points →
                </p>
              )}
            </button>
          );
        })}
      </div>

      <SourcesLine sources={documentsUsed} />
    </div>
  );
}

// ============================================================
// FLOWCHART
// ============================================================

function FlowchartView({
  data,
  documentsUsed,
  disabled,
  onRegenerate,
}: {
  data: FlowchartResult;
  documentsUsed: string[];
  disabled: boolean;
  onRegenerate: () => void;
}) {
  const [selectedConcept, setSelectedConcept] = useState<string | null>(null);

  const relatedConcepts = new Set<string>();

  if (selectedConcept) {
    for (const link of data.connections) {
      if (link.from === selectedConcept) {
        relatedConcepts.add(link.to);
      }

      if (link.to === selectedConcept) {
        relatedConcepts.add(link.from);
      }
    }
  }

  const visibleConnections = selectedConcept
    ? data.connections.filter(
        (link) => link.from === selectedConcept || link.to === selectedConcept
      )
    : data.connections;

  return (
    <div>
      <div className="flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
        <div>
          <div className="mb-3 inline-flex rounded-full bg-background px-4 py-2 text-xs font-medium text-accent">
            VISUAL LEARNING
          </div>
          <h3 className="font-serif text-3xl">
            {data.title || "Subject flowchart"}
          </h3>
          <p className="mt-2 text-sm text-muted">
            Click any concept to highlight what it connects to.
          </p>
        </div>

        <button
          onClick={onRegenerate}
          disabled={disabled}
          className="self-start rounded-full border border-border px-5 py-2.5 text-sm transition hover:bg-background disabled:opacity-40"
        >
          ↻ Regenerate
        </button>
      </div>

      {/* Stages */}
      <div className="mt-8">
        {data.stages.map((stage, index) => (
          <div key={index}>
            <div className="flex gap-4 md:gap-6">
              <div className="flex flex-col items-center">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-accent text-sm font-semibold text-white">
                  {index + 1}
                </div>
                {index < data.stages.length - 1 && (
                  <div className="w-px flex-1 bg-border" />
                )}
              </div>

              <div className="mb-6 flex-1 rounded-2xl border border-border bg-background p-5">
                <p className="font-serif text-xl">{stage.title}</p>

                {stage.description && (
                  <p className="mt-2 text-sm leading-6 text-muted">
                    {stage.description}
                  </p>
                )}

                {stage.concepts.length > 0 && (
                  <div className="mt-4 flex flex-wrap gap-2">
                    {stage.concepts.map((concept) => {
                      const isSelected = selectedConcept === concept;
                      const isRelated = relatedConcepts.has(concept);
                      const dimmed =
                        selectedConcept !== null && !isSelected && !isRelated;

                      return (
                        <button
                          key={concept}
                          onClick={() =>
                            setSelectedConcept(isSelected ? null : concept)
                          }
                          className={`rounded-full border px-3 py-1.5 text-xs font-medium transition ${
                            isSelected
                              ? "border-accent bg-accent text-white"
                              : isRelated
                                ? "border-accent bg-card text-accent"
                                : "border-border bg-card hover:border-accent"
                          } ${dimmed ? "opacity-40" : ""}`}
                        >
                          {concept}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Connections */}
      {data.connections.length > 0 && (
        <div className="mt-4 rounded-2xl bg-background p-6">
          <div className="flex items-center justify-between gap-3">
            <p className="text-xs font-medium tracking-wide text-accent">
              {selectedConcept
                ? `CONNECTIONS FOR "${selectedConcept.toUpperCase()}"`
                : "HOW CONCEPTS CONNECT"}
            </p>

            {selectedConcept && (
              <button
                onClick={() => setSelectedConcept(null)}
                className="text-xs text-muted underline-offset-4 hover:underline"
              >
                Show all
              </button>
            )}
          </div>

          {visibleConnections.length === 0 ? (
            <p className="mt-3 text-sm text-muted">
              No direct connections listed for this concept.
            </p>
          ) : (
            <div className="mt-4 space-y-2">
              {visibleConnections.map((link, index) => (
                <div
                  key={index}
                  className="flex flex-wrap items-center gap-2 text-sm"
                >
                  <button
                    onClick={() => setSelectedConcept(link.from)}
                    className="rounded-full border border-border bg-card px-3 py-1 font-medium hover:border-accent"
                  >
                    {link.from}
                  </button>
                  <span className="text-muted">— {link.relation} →</span>
                  <button
                    onClick={() => setSelectedConcept(link.to)}
                    className="rounded-full border border-border bg-card px-3 py-1 font-medium hover:border-accent"
                  >
                    {link.to}
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      <SourcesLine sources={documentsUsed} />
    </div>
  );
}